/*
 * A232867  Positions of the negative integers in the sequence (or tree) of
 *          complex numbers generated by these rules: 0 is in S, and if x is
 *          in S, then x + 1 and i*x are in S, where duplicates are deleted as
 *          they occur.
 * https://oeis.org/A232867
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(1) = 8; for n >= 2, a(n) = 2*(n-1)^2 + (n-1) + 9 (conjectured)
 * Range:     u8 n <= 11, u16 n <= 181, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;          /* undefined, return 0 for safety */
    if (n == 1) return (seq_t)8;
    seq_t m = (seq_t)(n - 1);              /* (n-1) fits in seq_t */
    return 2 * m * m + m + (seq_t)9;
}
